import json
import adapter_kit


def adapt(path):
    try:
        coords = adapter_kit.read_coordinates(path)
    except Exception:
        coords = []
    lines = []
    if coords:
        lines.append('Coordinate pairs found: %d' % len(coords))
        for i, pair in enumerate(coords[:10]):
            try:
                lat, lon = pair
                lines.append('Coordinate %d: latitude %s, longitude %s' % (i + 1, lat, lon))
                try:
                    summary = adapter_kit.coordinate_summary(lat, lon)
                    lines.append('Geographic summary: ' + json.dumps(summary, ensure_ascii=False, default=str))
                except Exception:
                    pass
                try:
                    places = adapter_kit.nearest_places(lat, lon)
                    lines.append('Nearby places: ' + json.dumps(places, ensure_ascii=False, default=str))
                except Exception:
                    pass
            except Exception:
                continue
    else:
        try:
            with open(path, 'rb') as f:
                raw = f.read(2048)
            lines.append('File content: ' + raw.decode('utf-8', errors='replace'))
        except Exception:
            lines.append('Unable to read coordinate content.')
    return {'text': '\n'.join(lines)[:4000]}
